<script setup lang="ts">
/**
 * 产品标识（用户提供的正式版）。
 *
 * **为什么不用 IconBase**：UI 图标统一取 Remix 集合（《前端设计规范》§3），
 * 但品牌标不是 UI 图标——它要能被认出来，混进通用图标集反而失去标识性。
 * 这里是一份独立的字标资产：同一份路径、同一套 `currentColor` 口径。
 *
 * ## 两档变体（v0.25）
 *
 * - `wordmark`（默认）：完整的 "KYLAB"。用在**需要把名字说出来的地方**
 *   （登录页、对话页空态）。
 * - `mark`：**只有那只实验烧瓶**——字标里充当 A 的那一只，含瓶里的液面与两颗气泡。
 *   用在**空间小、或名字已经在别处出现过**的地方：侧栏顶部就是这一档，
 *   在那里再写一遍 "KYLAB" 会跟下方的导航抢宽度，而烧瓶本身已经认得出来。
 *
 * 两档共用同一份路径数据，只是 viewBox 裁到各自的范围，所以笔画粗细天然一致
 * （换一份单独画的图标就会对不上）。`mark` 里保留了液面与气泡——去掉它们是另一只瓶子，
 * 与字标里那只对不上。
 *
 * ## 两点处理（**路径数据原样保留**，只改容器）
 *
 * - 去掉原始画布的留白：原图 1536×1024，字标只占 x∈[89,1464]、y∈[318,648]，
 *   沿用原 viewBox 会在四周各留一大段空白，字标看起来只有一半大；
 * - `fill` 改成 `currentColor`：原文件写死 #030302，深色主题下等于看不见。
 *   注意 `fill-rule="evenodd"` **必须留在每个 path 上**：字标是描摹出来的，
 *   靠奇偶规则挖空笔画内部的孔洞，换到外层容器上会让字形变成一圈轮廓。
 *
 * 高度用 `size` 控制、宽度按各档真实比例算，调用方只说"要高多少"。
 */
const props = withDefaults(
  defineProps<{
    /** 高度（px）。宽度按该变体的真实比例自动算。 */
    size?: number
    /** `wordmark` 完整字标 / `mark` 只有烧瓶。 */
    variant?: 'wordmark' | 'mark'
    /** 无障碍名。字标是图形，屏幕阅读器要靠它知道这是什么。 */
    label?: string
  }>(),
  { size: 20, variant: 'wordmark', label: 'KYLAB 知识库' },
)

/**
 * 两档的 viewBox 与宽高比。数值是从路径数据里量出来的：
 * 字标 x∈[89,1464] y∈[318,648]（含右上角那颗星）；
 * 烧瓶 x∈[883,1132] y∈[379,648]（含液面与气泡）。
 */
const VARIANTS = {
  wordmark: { viewBox: '89 318 1375 330', ratio: 1375 / 330 },
  mark: { viewBox: '883 379 249 269', ratio: 249 / 269 },
} as const

const box = VARIANTS[props.variant]
</script>

